INSERT INTO public.landings (tipo, clave, contenido_es, contenido_en)
VALUES
  ('familia', 'actividades-vida-diaria', $ime_landing${"name":"Actividades de la vida diaria","title":"Ayudas para actividades de la vida diaria | I-ME","description":"Ayudas, accesorios y equipos para movilidad cotidiana, higiene y transferencia en instituciones y cuidado asistido.","intro":"Esta familia reúne ayudas para tareas cotidianas, higiene, transferencia y apoyo funcional. La selección depende del usuario, el entorno y la compatibilidad entre equipo y accesorio.","body":["Antes de cotizar conviene documentar espacio, recorrido, tipo de asistencia, frecuencia de uso y limpieza.","Arneses, asientos, baldes, actuadores y repuestos se validan por referencia; piezas parecidas no son automáticamente compatibles."],"faq":[{"q":"¿Cómo confirmo compatibilidad de un accesorio?","a":"Con modelo, referencia y ficha del equipo principal. I-ME confirma la correspondencia antes de cotizar."}]}$ime_landing$::jsonb, $ime_landing${"name":"Activities of daily living","title":"Daily living aids and institutional equipment | I-ME","description":"Aids, accessories and equipment for daily mobility, hygiene and transfer in institutions and assisted care.","intro":"This family brings together aids for daily tasks, hygiene, transfer and functional support. Selection depends on user, environment and equipment-accessory compatibility.","body":["Before quoting, document space, route, assistance type, use frequency and cleaning.","Slings, seats, buckets, actuators and spare parts are validated per model; similar-looking parts are not automatically compatible."],"faq":[{"q":"How do I confirm accessory compatibility?","a":"Use model, reference and main-equipment documentation. I-ME confirms fit before quoting."}]}$ime_landing$::jsonb),
  ('familia', 'diagnostico-clinico-basico', $ime_landing${"name":"Diagnóstico clínico básico","title":"Equipos de diagnóstico clínico y laboratorio básico | I-ME","description":"Equipos de diagnóstico clínico básico y laboratorio para instituciones: analizadores, medición y referencias documentadas.","intro":"El diagnóstico básico reúne tecnologías distintas. Para comparar correctamente hay que separar medición clínica, procesamiento de muestras, capacidad y flujo documental.","body":["El volumen esperado, tipo de muestra o medición, espacio, consumibles y gestión de resultados definen la tipología.","Cada analizador o equipo se revisa contra documentación oficial, requisitos de instalación y alcance de capacitación y soporte."],"faq":[{"q":"¿Qué información necesita una cotización?","a":"Tipo de prueba o medición, volumen, infraestructura, consumibles y flujo de resultados."}]}$ime_landing$::jsonb, $ime_landing${"name":"Basic clinical diagnostics","title":"Basic clinical and laboratory diagnostic equipment | I-ME","description":"Basic clinical and laboratory diagnostic equipment for institutions: analyzers, measurement and documented models.","intro":"Basic diagnostics includes different technologies. Sound comparison separates clinical measurement, sample processing, capacity and documentation workflow.","body":["Expected volume, sample or measurement type, space, consumables and result management define the equipment class.","Each analyzer or device is reviewed against official documentation, installation requirements, training and support scope."],"faq":[{"q":"What information is needed for a quote?","a":"Test or measurement type, volume, infrastructure, consumables and result workflow."}]}$ime_landing$::jsonb),
  ('familia', 'emergencias-traslado-inmovilizacion', $ime_landing${"name":"Emergencias, traslado e inmovilización","title":"Traslado, inmovilización y urgencias hospitalarias | I-ME","description":"Equipos de traslado, tableros e inmovilización para urgencias. Las camillas de traslado se cotizan en la guía de camillas médicas.","intro":"Traslado e inmovilización se dimensionan por recorrido, vehículo o área, manipulación, almacenamiento y protocolo institucional.","body":["Camillas de ambulancia, plegables, cuchara, tableros y accesorios responden a escenarios operativos diferentes.","Antes de comprar se revisan dimensiones, carga declarada, plegado, anclaje, limpieza, accesorios y mantenimiento según fabricante."],"faq":[{"q":"¿Una camilla sirve para cualquier ambulancia?","a":"No se debe asumir. Hay que validar dimensiones, sistema de anclaje y referencia del vehículo o instalación."},{"q":"¿Qué camilla necesito para urgencias o procedimientos?","a":"Camilla de ambulancia, plegable, de procedimientos o cuchara responden a usos distintos. Documente recorrido, manipulación y protocolo antes de cotizar."}]}$ime_landing$::jsonb, $ime_landing${"name":"Emergency, transport and immobilization","title":"Hospital transport, immobilization and emergency equipment | I-ME","description":"Transport equipment, spine boards and immobilization for emergency services. Transfer stretchers are quoted on the medical stretchers guide.","intro":"Transport and immobilization are sized by route, vehicle or area, handling, storage and institutional protocol.","body":["Ambulance, folding and scoop stretchers, spine boards and accessories fit different operating scenarios.","Before purchase, review dimensions, declared load, folding, anchoring, cleaning, accessories and maintenance per manufacturer."],"faq":[{"q":"Does one stretcher fit every ambulance?","a":"Do not assume so. Validate dimensions, anchoring system and vehicle or installation reference."},{"q":"Which stretcher do I need for ER or procedures?","a":"Ambulance, folding, procedure or scoop stretchers fit different uses. Document route, handling and protocol before quoting."}]}$ime_landing$::jsonb),
  ('familia', 'esterilizacion-control-infecciones', $ime_landing${"name":"Esterilización y control de infecciones","title":"Esterilización y control de infecciones hospitalarias | I-ME","description":"Autoclaves, esterilizadores, desinfección y apoyo para centrales e instituciones de salud.","intro":"Esta familia combina procesos, equipos y consumibles. La compra debe partir del material a procesar, capacidad, ciclo, infraestructura y trazabilidad requeridos.","body":["Autoclaves, esterilizadores y sistemas de desinfección no son intercambiables: cada tecnología tiene alcance y condiciones documentadas.","Se validan agua, energía, ventilación, drenaje, carga, instalación, capacitación y mantenimiento para la referencia seleccionada."],"faq":[{"q":"¿Cómo se define capacidad?","a":"Desde tipos de carga, volumen por jornada y flujo de la central; no solo por litros nominales."}]}$ime_landing$::jsonb, $ime_landing${"name":"Sterilization and infection control","title":"Hospital sterilization and infection-control equipment | I-ME","description":"Autoclaves, sterilizers, disinfection and support equipment for sterile services and healthcare institutions.","intro":"This family combines processes, equipment and consumables. Purchasing starts from processed material, capacity, cycle, infrastructure and traceability needs.","body":["Autoclaves, sterilizers and disinfection systems are not interchangeable: each technology has documented scope and conditions.","Water, power, ventilation, drainage, load, installation, training and maintenance are validated for the selected model."],"faq":[{"q":"How is capacity defined?","a":"From load types, daily volume and sterile-services workflow—not nominal liters alone."}]}$ime_landing$::jsonb),
  ('familia', 'insumos-accesorios', $ime_landing${"name":"Insumos y accesorios","title":"Insumos y accesorios para equipos biomédicos | I-ME","description":"Circuitos, cables, interfaces, repuestos y accesorios identificados por modelo para equipos biomédicos.","intro":"En accesorios, compatibilidad y trazabilidad importan más que la apariencia. Cada pedido debe identificar equipo principal, marca, modelo y referencia.","body":["El catálogo incluye circuitos, cables, interfaces, mezcladores, arneses y repuestos para distintas líneas.","I-ME confirma presentación, compatibilidad, unidad de empaque y disponibilidad dentro de la propuesta formal."],"faq":[{"q":"¿Puedo comprar por fotografía?","a":"No es suficiente. Envíe etiqueta, modelo y referencia del equipo para reducir errores de compatibilidad."}]}$ime_landing$::jsonb, $ime_landing${"name":"Consumables and accessories","title":"Biomedical equipment consumables and accessories | I-ME","description":"Circuits, cables, interfaces, spare parts and accessories identified by model for biomedical equipment.","intro":"For accessories, compatibility and traceability matter more than appearance. Each order should identify main equipment, brand, model and reference.","body":["The catalog includes circuits, cables, interfaces, blenders, harnesses and spare parts across different lines.","I-ME confirms presentation, compatibility, pack unit and availability in the formal proposal."],"faq":[{"q":"Can I purchase from a photo?","a":"A photo is not enough. Send label, model and equipment reference to reduce compatibility errors."}]}$ime_landing$::jsonb),
  ('familia', 'mobiliario', $ime_landing${"name":"Cama hospitalaria y cama eléctrica","title":"Cama hospitalaria eléctrica para clínicas de Colombia | I-ME","description":"Cama hospitalaria y cama eléctrica hospitalaria para clínicas en Colombia. Compare B-1000 Pro, B-2000 y B-2000 Plus y cotice la configuración del servicio.","intro":"La cama hospitalaria se define por el servicio, el personal y el recorrido del área. La cama eléctrica hospitalaria cambia de posición con motores; la manual, con manivelas. Las dos se cotizan por referencia, no como un mueble genérico.","body":["En el catálogo activo están la cama eléctrica Advanced B-1000 Pro, la B-2000 Plus y la Saikang V6K, y la cama hospitalaria manual Advanced B-2000. Las funciones y medidas de cada una están en su página; no se trasladan de un modelo a otro.","Esta familia también reúne camillas, carros y mesas del mismo entorno clínico. Las camillas de traslado están en emergencias, y las camas obstétricas en neonatología. Para cotizar, indique el espacio útil, las puertas y el uso previsto."],"faq":[{"q":"¿Qué diferencia una cama eléctrica hospitalaria de una manual?","a":"La eléctrica ajusta la posición con motores y la manual con manivelas. Cuál conviene depende del servicio, del personal y del espacio. La configuración de cada referencia se confirma en su página y en la cotización."},{"q":"¿Qué medidas debo enviar?","a":"Espacio útil, puertas, ascensores, recorridos y restricciones del área, además del uso previsto."}]}$ime_landing$::jsonb, $ime_landing${"name":"Hospital beds in Colombia","title":"Electric hospital bed Colombia for clinics and wards | I-ME","description":"Electric and manual hospital beds for wards and ICU in Colombia. Compare B-1000 Pro, B-2000 and B-2000 Plus, then request a quote for your service.","intro":"A hospital bed in Colombia is chosen for the ward, the staff and the route through the building. An electric hospital bed changes position with motors; a manual bed uses cranks. Both are quoted by reference, not as generic furniture.","body":["Active electric hospital beds include the Advanced B-1000 Pro, the B-2000 Plus and the Saikang V6K. The Advanced B-2000 is a manual hospital bed. Functions and dimensions stay on each product page; they are not copied from one model to another.","The same family also lists stretchers, carts and tables used on those wards. Transfer stretchers are in the emergency family, and obstetric beds are with neonatology. When you request a quote, send usable space, doors and the intended service."],"faq":[{"q":"How does an electric hospital bed differ from a manual one?","a":"An electric bed changes position with motors; a manual bed uses cranks. Which one fits depends on the service, the staff and the room. Each reference’s configuration is confirmed on its page and in the quote."},{"q":"Which measurements should I send?","a":"Usable space, doors, elevators, routes and area restrictions, plus intended use."}]}$ime_landing$::jsonb),
  ('familia', 'movilidad-rehabilitacion', $ime_landing${"name":"Movilidad y rehabilitación","title":"Caminadores para adultos y sillas Konfort Plus | Movilidad | I-ME","description":"Caminadores para adultos, rollators Konfort Plus, sillas de ruedas estándar y transporte. Orientación y cotización institucional en Colombia.","intro":"Movilidad no se resuelve solo con talla. Entorno, postura, transferencia, autonomía, acompañante y mantenimiento determinan la configuración.","body":["La familia incluye sillas, bastones, muletas, ayudas de transferencia y repuestos identificados por modelo.","La selección institucional debe documentar recorrido, almacenamiento, ajuste y compatibilidad; la evaluación individual corresponde al profesional responsable."],"faq":[{"q":"¿Cómo elijo una silla o ayuda de marcha?","a":"I-ME compara referencias y entorno; la indicación y ajuste individual deben confirmarse por el profesional competente."},{"q":"¿Tienen caminadores para adultos Konfort Plus?","a":"Sí. Hay caminadores y rollators Konfort Plus en catálogo. Para orientación por uso y presupuesto, consulte la guía de caminadores o solicite cotización."},{"q":"¿Venden sillas de ruedas Konfort Plus?","a":"Sí. Konfort Plus incluye sillas estándar, transporte y reclinables publicadas en catálogo. Confirmamos variante y disponibilidad al cotizar."}]}$ime_landing$::jsonb, $ime_landing${"name":"Mobility and rehabilitation","title":"Adult walkers & Konfort Plus wheelchairs | Mobility | I-ME","description":"Adult walkers, Konfort Plus rollators and wheelchairs — standard and transport models. Institutional guidance and quotes in Colombia.","intro":"Mobility is not solved by size alone. Environment, posture, transfer, independence, caregiver and maintenance determine configuration.","body":["This family includes wheelchairs, canes, crutches, transfer aids and model-identified spare parts.","Institutional selection should document route, storage, adjustment and compatibility; individual assessment belongs to the responsible professional."],"faq":[{"q":"How do I choose a wheelchair or walking aid?","a":"I-ME compares models and environment; individual prescription and fitting must be confirmed by the competent professional."},{"q":"Do you carry Konfort Plus adult walkers?","a":"Yes. Konfort Plus walkers and rollators are in the catalog. For use-case and budget guidance, see the walkers hub or request a quote."},{"q":"Do you sell Konfort Plus wheelchairs?","a":"Yes. Konfort Plus standard, transport and reclining wheelchairs are published in the catalog. We confirm variant and availability when quoting."}]}$ime_landing$::jsonb),
  ('familia', 'ortopedia-confort', $ime_landing${"name":"Ortopedia y confort","title":"Productos de ortopedia y confort institucional | I-ME","description":"Cabestrillos, fajas y productos de soporte y confort identificados por talla y referencia.","intro":"Talla, referencia y uso indicado por el profesional responsable deben confirmarse antes de seleccionar productos de soporte y confort.","body":["El catálogo separa referencias y tallas para evitar tratar productos visualmente parecidos como equivalentes.","I-ME confirma presentación y disponibilidad comercial; no realiza prescripción ni ajuste clínico."],"faq":[{"q":"¿I-ME recomienda talla o tratamiento?","a":"No. La talla y el uso deben venir definidos por el profesional responsable; I-ME confirma la referencia comercial."}]}$ime_landing$::jsonb, $ime_landing${"name":"Orthopedics and comfort","title":"Orthopedic and comfort products for institutions | I-ME","description":"Slings, binders and support and comfort products identified by size and reference.","intro":"Size, model and use indicated by the responsible professional should be confirmed before selecting support and comfort products.","body":["The catalog separates models and sizes so visually similar products are not treated as equivalents.","I-ME confirms commercial presentation and availability; it does not prescribe or perform clinical fitting."],"faq":[{"q":"Does I-ME recommend size or treatment?","a":"No. Size and use must be defined by the responsible professional; I-ME confirms the commercial model."}]}$ime_landing$::jsonb),
  ('familia', 'terapia-respiratoria-soporte-vital', $ime_landing${"name":"Terapia respiratoria y soporte vital","title":"Nebulizadores, aspiradores y terapia respiratoria | I-ME","description":"Nebulizadores, aspiradores de secreciones, oxígeno y ventiladores publicados para terapia respiratoria en Colombia. El alto flujo Airvo no está en el catálogo activo.","intro":"La familia respiratoria combina equipos y accesorios con funciones distintas. Entorno, gases, flujo, población y protocolo institucional definen la selección.","body":["Aspiradores, mezcladores, humidificación e interfaces deben compararse por función y compatibilidad documentada.","Antes de cotizar se validan infraestructura, accesorios, consumibles, limpieza, capacitación y mantenimiento por referencia."],"faq":[{"q":"¿Todos los accesorios respiratorios son compatibles?","a":"No se debe asumir. Modelo, conexión, rango y documentación del fabricante deben coincidir."},{"q":"¿Tienen sistemas de alto flujo Fisher Paykel?","a":"Airvo y los circuitos Optiflow no están en el catálogo activo. La familia publicada incluye nebulizadores, aspiradores, oxígeno, CPAP neonatal y ventiladores Saikang. La referencia se confirma al cotizar."}]}$ime_landing$::jsonb, $ime_landing${"name":"Respiratory therapy and life support","title":"Nebulizers, suction units and respiratory therapy | I-ME","description":"Published nebulizers, suction units, oxygen and ventilators for respiratory therapy in Colombia. Airvo high-flow systems are not in the active catalog.","intro":"The respiratory family combines equipment and accessories with different functions. Setting, gases, flow, population and institutional protocol define selection.","body":["Suction units, blenders, humidification and interfaces should be compared by function and documented compatibility.","Before quoting, infrastructure, accessories, consumables, cleaning, training and maintenance are validated per model."],"faq":[{"q":"Are all respiratory accessories compatible?","a":"Do not assume so. Model, connection, range and manufacturer documentation must match."},{"q":"Do you carry Fisher Paykel high-flow systems?","a":"Airvo and Optiflow circuits are not in the active catalog. The published family includes nebulizers, suction units, oxygen, neonatal CPAP and Saikang ventilators. The reference is confirmed when quoting."}]}$ime_landing$::jsonb),
  ('familia', 'robots', $ime_landing${"name":"Robots de servicio e ingeniería robótica en Colombia","title":"Robots de servicio e ingeniería robótica en Colombia | I-ME","description":"Distribuidores de robots en Colombia: recepción, telepresencia, limpieza autónoma, logística AMR e ingeniería con LiDAR SLAM.","intro":"I-ME distribuye robots de servicio en Colombia y hace la ingeniería de integración: recepción, telepresencia, logística intrahospitalaria, limpieza autónoma y educación, con navegación LiDAR SLAM sobre el plano real de la sede.","body":["El catálogo activo reúne ocho referencias: PadBot X3 y PadBot X2 (recepción), Cruzr (humanoide y Open API), PadBot P2 (telepresencia), PadBot W2 (gabinete PIN/QR), PadBot W3s (bandejas), robot C3 (limpieza 3-en-1) y PadBot T2 (educación y acompañamiento).","La comparación empieza por el edificio: recorridos, puertas, ascensores, superficies, puntos de carga y el responsable de operación. La integración multiplanta usa puntos de espera y abordaje de ascensor (módulo IoT E-Box o API Cloud) y puntos de control de acceso.","Otras arquitecturas —limpieza industrial pesada, desinfección UV-C o logística cerrada— se estudian como ingeniería bajo proyecto y no se publican como SKUs nuevos. La garantía es la del fabricante, con soporte electromecánico local de I-ME."],"faq":[{"q":"¿I-ME es un distribuidor de robots de servicio en Colombia?","a":"Sí. Publica ocho robots de recepción, telepresencia, logística, limpieza y educación, y acompaña la ingeniería de integración en la sede. El alcance se confirma en la propuesta."},{"q":"¿Puede integrarse con ascensores o torniquetes?","a":"En los modelos cuyo manual lo describe, sí: puntos de espera y abordaje de ascensor con módulo IoT E-Box o API Cloud, y control de acceso para puertas y torniquetes. Se valida en el plano de la sede."},{"q":"¿La navegación exige obra civil o cinta magnética?","a":"Los manuales de esta línea describen mapas SLAM con LiDAR, sin reflectores ni balizas magnéticas. Sensores de ultrasonido, anticaída y parachoques cubren vidrio, escaleras y contacto."}]}$ime_landing$::jsonb, $ime_landing${"name":"Service robots and robotics engineering in Colombia","title":"Service robots and robotics engineering in Colombia | I-ME","description":"Robot distributors in Colombia: reception, telepresence, autonomous cleaning, AMR logistics and LiDAR SLAM engineering.","intro":"I-ME distributes service robots in Colombia and engineers the integration: reception, telepresence, in-hospital logistics, autonomous cleaning and education, with LiDAR SLAM navigation on the real floor plan.","body":["The active catalog has eight references: PadBot X3 and PadBot X2 (reception), Cruzr (humanoid and Open API), PadBot P2 (telepresence), PadBot W2 (PIN/QR cabinet), PadBot W3s (trays), the C3 robot (3-in-1 cleaning) and PadBot T2 (education and companionship).","Comparison starts with the building: routes, doors, elevators, floors, charge points and the operating owner. Multi-floor integration uses elevator waiting and boarding points (E-Box IoT module or cloud API) and access-control points.","Other architectures — heavy industrial cleaning, UV-C disinfection or closed logistics — are studied as project engineering and are not published as new SKUs. Warranty is the manufacturer’s, with local electromechanical support from I-ME."],"faq":[{"q":"Is I-ME a service-robot distributor in Colombia?","a":"Yes. It publishes eight reception, telepresence, logistics, cleaning and education robots, and supports on-site integration engineering. Scope is confirmed in the proposal."},{"q":"Can it integrate with elevators or turnstiles?","a":"On models whose manual describes it, yes: elevator waiting and boarding points via the E-Box IoT module or a cloud API, and access control for doors and turnstiles. It is validated on the site drawing."},{"q":"Does navigation require civil works or magnetic tape?","a":"Manuals for this line describe SLAM maps with LiDAR, without reflectors or magnetic beacons. Ultrasound, cliff sensors and bumpers cover glass, stairs and contact."}]}$ime_landing$::jsonb),
  ('familia', 'radiologia', $ime_landing${"name":"Imagenología y radiología","title":"Mamografía digital y equipos de imagenología hospitalaria | I-ME","description":"Equipos de radiología e imagenología para instituciones de salud en Colombia: rayos X, detectores, mamografía y fluoroscopia.","intro":"Un proyecto de imagenología se define por flujo de pacientes, espacio disponible e integración con la operación radiológica; no por una ficha aislada.","body":["I-ME acompaña la selección de tipología — sistemas DR de techo, piso o móvil, detectores planos, mamografía y arco en C — según el servicio y el flujo previsto.","Antes de cotizar se revisan condiciones de sala, requerimientos de instalación, integración y documentación aplicable para cada referencia. La validación regulatoria se confirma por equipo.","Para renovaciones o aperturas de servicio, se puede estructurar una lista de equipos alrededor de prioridades operativas y del alcance definido por la institución."],"faq":[{"q":"¿Sistema DR móvil, de piso o de techo?","a":"Cada tipología responde a un flujo y una infraestructura distintos. Revisamos volumen, movilidad requerida y condiciones de la sala antes de proponer referencias."},{"q":"¿La documentación regulatoria está disponible?","a":"La documentación aplicable se valida para la referencia cotizada; no se generaliza entre equipos."}]}$ime_landing$::jsonb, $ime_landing${"name":"Medical imaging and radiology","title":"Digital mammography & hospital imaging equipment | I-ME","description":"Radiology and medical imaging equipment for healthcare institutions in Colombia: X-ray, detectors, mammography and fluoroscopy.","intro":"An imaging project follows patient flow, available space and radiology operations—not a single product sheet.","body":["I-ME supports modality selection—ceiling, floor and mobile DR systems, flat-panel detectors, mammography and C-arms—by service and expected workflow.","Before quoting, we review room conditions, installation requirements, integration and applicable documentation for each SKU. Regulatory validation is confirmed per device.","For renewals or new services, equipment lists can be structured around operational priorities and the institution-defined scope."],"faq":[{"q":"Mobile, floor-mounted or ceiling-mounted DR?","a":"Each modality fits a different workflow and infrastructure. We review volume, mobility needs and room conditions before proposing SKUs."},{"q":"Is regulatory documentation available?","a":"Applicable documentation is validated for the quoted SKU; it is not generalized across devices."}]}$ime_landing$::jsonb),
  ('familia', 'monitores', $ime_landing${"name":"Monitores de signos vitales","title":"Monitores Biolight S12/M12 y multiparamétricos UCI | I-ME","description":"Monitores de paciente Biolight S12, M12 y multiparamétricos UCI para hospitales. Orientación I-ME: parámetros, modularidad y soporte en Colombia.","intro":"Elegir un monitor no es solo “pantalla grande”. En UCI, urgencias o transporte el criterio cambia: parámetros base, modularidad, alarma usable y cómo se integra a la estación central.","body":["En Colombia, las instituciones suelen pedir monitores multiparamétricos con ECG, SpO₂ y NIBP como mínimo, y opciones de capnografía o presión invasiva según el servicio. I-ME ayuda a mapear el uso previsto antes de cotizar referencias.","También importa el flujo operativo: ¿quién responde alarmas?, ¿hay central multicama?, ¿se necesita transporte inter-área sin perder trazo? Esas preguntas evitan comprar potencia que no se usa o quedar cortos en criticidad.","Los monitores de paciente Biolight S12 y M12 están a la venta, con precio bajo cotización. También está el Advanced PM-2000A PRO. La documentación y el soporte se confirman por referencia."],"faq":[{"q":"¿Qué diferencia un monitor básico de uno de UCI?","a":"La criticidad del servicio: parámetros expandibles, alarmas, autonomía y capacidad de central. Lo básico cubre observación; UCI suele exigir más modularidad y continuidad."},{"q":"¿I-ME instala y capacita?","a":"Sí, el alcance de instalación y capacitación se acuerda en la cotización según sede y cantidad de puntos."},{"q":"¿Tienen el monitor Biolight S12 y el M12?","a":"Sí. El S12 y el M12 están en el catálogo activo, con precio bajo cotización. Otros monitores Biolight retirados no se publican."}]}$ime_landing$::jsonb, $ime_landing${"name":"Patient monitors","title":"Biolight S12/M12 & ICU multiparameter monitors | I-ME","description":"Biolight S12, M12 and ICU multiparameter patient monitors for hospitals. I-ME guidance on parameters, modularity and support in Colombia.","intro":"Choosing a monitor is not just “a bigger screen”. ICU, ER or transport change the brief: core parameters, modularity, usable alarms and how it joins a central station.","body":["Colombian hospitals often need multiparameter monitors with ECG, SpO₂ and NIBP as a baseline, plus capnography or invasive pressure by service. I-ME maps intended use before quoting SKUs.","Operations matter too: who owns alarms, whether a multi-bed central exists, and whether transport must keep the trace. That prevents overbuying or under-specifying critical care.","Biolight S12 and M12 patient monitors are for sale, with price on request. The Advanced PM-2000A PRO is also published. Documentation and support are confirmed per reference."],"faq":[{"q":"What separates a basic monitor from an ICU monitor?","a":"Service criticality: expandable parameters, alarms, autonomy and central-station readiness. Basic units fit observation; ICU usually needs modularity and continuity."},{"q":"Does I-ME install and train?","a":"Yes — installation and training scope are agreed in the quote by site and number of points."},{"q":"Do you carry the Biolight S12 and M12 monitors?","a":"Yes. The S12 and the M12 are in the active catalog, with price on request. Other withdrawn Biolight monitors are not published."}]}$ime_landing$::jsonb),
  ('familia', 'cardiologia', $ime_landing${"name":"Cardiología","title":"Equipos de cardiología hospitalaria | ECG y más | I-ME","description":"Cardiología para hospitales y clínicas en Colombia: electrocardiógrafos y flujo diagnóstico. Asesoría I-ME sin inventar indicaciones clínicas.","intro":"En cardiología ambulatoria y hospitalaria el cuello de botella suele ser el flujo: derivaciones, portabilidad, informe y quién interpreta — no solo el “ECG más barato”.","body":["Las instituciones preguntan por 3, 6 o 12 derivaciones, impresión/archivo digital y facilidad de uso en consulta o urgencias. I-ME orienta según volumen de pacientes y perfil del servicio.","Cuando el proyecto incluye desfibrilación o monitoreo continuo, se separa tipología (diagnóstico vs reanimación) para no mezclar compras.","Cotizamos con soporte y opciones de financiamiento institucional cuando aplica."],"faq":[{"q":"¿ECG de 12 derivaciones para consulta externa?","a":"Es el estándar más pedido en diagnóstico. Confirmamos software, impresión y flujo de historia clínica en la visita técnica."}]}$ime_landing$::jsonb, $ime_landing${"name":"Cardiology","title":"Hospital cardiology equipment | ECG and more | I-ME","description":"Cardiology for hospitals and clinics in Colombia: electrocardiographs and diagnostic flow. I-ME advisory without inventing clinical claims.","intro":"In outpatient and hospital cardiology the bottleneck is usually workflow: leads, portability, reporting and who interprets — not only the cheapest ECG.","body":["Sites ask about 3/6/12 leads, print or digital archive, and ease of use in clinic or ER. I-ME orients by patient volume and service profile.","When defibrillation or continuous monitoring is in scope, we separate diagnostic vs resuscitation typologies so purchases stay coherent.","Quotes include support and institutional financing options when applicable."],"faq":[{"q":"Is a 12-lead ECG right for outpatient clinic?","a":"It is the most requested diagnostic baseline. We confirm software, printing and EMR workflow in the technical visit."}]}$ime_landing$::jsonb),
  ('familia', 'cardiologia-reanimacion', $ime_landing${"name":"Cardiología y reanimación","title":"Cardiología y reanimación hospitalaria | I-ME","description":"Electrocardiógrafos, Holter y reanimación para hospitales en Colombia. El desfibrilador bifásico se cotiza en su guía.","intro":"Un desfibrilador no se elige por brochure: se define por protocolo de código, quién lo opera y dónde vive el equipo (urgencias, UCI, quirófano, ambulancia).","body":["Pedimos aclarar uso previsto (DEA vs manual/monitor), capacitación y plan de mantenimiento. Documentación regulatoria se valida por referencia — sin inventar registros.","I-ME cubre cotización, puesta en marcha acordada y soporte para instituciones en todo el país."],"faq":[{"q":"¿Necesito desfibrilador con monitor?","a":"Depende del servicio: urgencias y UCI suelen requerir monitoreo; otros puntos pueden priorizar DEA. Lo definimos con biomédica y jefatura clínica."}]}$ime_landing$::jsonb, $ime_landing${"name":"Cardiology and resuscitation","title":"Hospital cardiology and resuscitation equipment | I-ME","description":"Electrocardiographs, Holter and resuscitation equipment for hospitals in Colombia. The biphasic defibrillator is quoted on its guide.","intro":"A defibrillator is not chosen from a brochure: it follows code protocol, who operates it and where it lives (ER, ICU, OR, ambulance).","body":["We clarify intended use (AED vs manual/monitor), training and maintenance plan. Regulatory docs are validated per SKU — never invented.","I-ME covers quoting, agreed commissioning and support for institutions nationwide."],"faq":[{"q":"Do I need a defibrillator with monitor?","a":"It depends on the service: ER/ICU often need monitoring; other points may prioritize AED. We define it with biomed and clinical leads."}]}$ime_landing$::jsonb),
  ('familia', 'sala-cirugia', $ime_landing${"name":"Sala de cirugía","title":"Equipos de sala de cirugía hospitalaria | I-ME","description":"Mesas quirúrgicas, iluminación y flujo de quirófano para hospitales en Colombia. Asesoría I-ME orientada a carga quirúrgica real.","intro":"Quirófano se dimensiona por especialidades, tiempos de cambio y ergonomía — no por “paquete completo” genérico.","body":["Mesas eléctricas/hidráulicas, radiolúcidas u ortopédicas responden a preguntas distintas. I-ME separa tipologías antes de cotizar referencias.","También alineamos lámparas, aspiración y mobiliario perioperatorio cuando el proyecto es de sala completa."],"faq":[{"q":"¿Mesa ortopédica o multipropósito?","a":"Depende del mix quirúrgico. Si hay traumatología frecuente, la radiolúcida/ortopédica suele priorizarse; si no, multipropósito puede bastar."}]}$ime_landing$::jsonb, $ime_landing${"name":"Operating room","title":"Hospital operating room equipment | I-ME","description":"Surgical tables, lighting and OR flow for hospitals in Colombia. I-ME advisory driven by real surgical load.","intro":"OR sizing follows specialties, turnover time and ergonomics — not a generic “full package”.","body":["Electric/hydraulic, radiolucent or orthopedic tables answer different questions. I-ME separates typologies before quoting SKUs.","We also align lights, suction and perioperative furniture when the project is a full room."],"faq":[{"q":"Orthopedic or multipurpose table?","a":"It depends on case mix. Frequent trauma often prioritizes radiolucent/orthopedic; otherwise multipurpose may suffice."}]}$ime_landing$::jsonb),
  ('familia', 'neonatologia', $ime_landing${"name":"Neonatología","title":"Equipos de neonatología hospitalaria | I-ME","description":"Incubadoras, servocunas y soporte neonatal para hospitales en Colombia. Orientación I-ME según nivel de cuidado.","intro":"Neonatología exige tipología clara: incubadora cerrada, abierta/servocuna, fototerapia o CPAP — según nivel y protocolo institucional.","body":["Ayudamos a biomédica y pediatría a traducir el nivel de cuidado en una lista corta de tipologías, evitando mezclar consumibles con equipos capitales sin plan de soporte."],"faq":[{"q":"¿Incubadora abierta o cerrada?","a":"Depende del nivel neonatal y del procedimiento. Lo definimos con el servicio clínico; no hay una sola respuesta “correcta” de catálogo."}]}$ime_landing$::jsonb, $ime_landing${"name":"Neonatology","title":"Hospital neonatology equipment | I-ME","description":"Incubators, warmers and neonatal support for hospitals in Colombia. I-ME guidance by care level.","intro":"Neonatology needs clear typology: closed incubator, open warmer, phototherapy or CPAP — by care level and protocol.","body":["We help biomed and pediatrics translate care level into a short typology list, avoiding mixing consumables with capital equipment without a support plan."],"faq":[{"q":"Open or closed incubator?","a":"It depends on neonatal level and procedures. We define it with the clinical service; there is no single catalog “right answer”."}]}$ime_landing$::jsonb),
  ('familia', 'ultrasonido', $ime_landing${"name":"Equipos de ultrasonido y ecógrafos en Colombia","title":"Ecógrafos Colombia: equipos de ultrasonido hospitalario | I-ME","description":"Equipos de ultrasonido y ecógrafos en Colombia para hospitales y clínicas. Compare las referencias del catálogo I-ME y solicite cotización por modelo.","intro":"Equipos de ultrasonido y ecógrafos en Colombia se cotizan por referencia: el catálogo reúne los sistemas DUS y los ecógrafos portátiles publicados. El precio, la sonda y la documentación se confirman en cada ficha, no en un texto genérico.","body":["En el catálogo activo están DUS-3000, DUS-5000, DUS-5000 Plus, DUS-6000 y DUS-7000, el ecógrafo Color Doppler diagnóstico vascular, el ecógrafo portátil con WiFi y DICOM y el ultrasonido point-of-care pocket.","Separar ecógrafo de consulta y equipo point-of-care evita mezclar fichas. Lo que cada modelo hace está en su página."],"faq":[{"q":"¿Necesito DICOM sí o sí?","a":"Si el hospital exige PACS/HIS, sí. En consulta pequeña puede bastar archivo local; lo confirmamos con sistemas."}]}$ime_landing$::jsonb, $ime_landing${"name":"Ultrasound equipment and scanners in Colombia","title":"Hospital ultrasound equipment and scanners in Colombia | I-ME","description":"Ultrasound equipment and scanners for hospitals and clinics in Colombia. Compare I-ME catalog references and request a quote by model.","intro":"Ultrasound equipment in Colombia is quoted by reference: the catalog lists the published DUS systems and portable scanners. Price, probe and documentation are confirmed on each sheet, not in a generic paragraph.","body":["The active catalog includes DUS-3000, DUS-5000, DUS-5000 Plus, DUS-6000 and DUS-7000, the color Doppler vascular scanner, the portable WiFi DICOM scanner and the pocket point-of-care ultrasound.","Separating a clinic scanner from a point-of-care unit avoids mixing sheets. What each model does stays on its page."],"faq":[{"q":"Is DICOM mandatory?","a":"If the hospital requires PACS/HIS, yes. A small clinic may store locally; we confirm with IT."}]}$ime_landing$::jsonb),
  ('familia', 'soluciones-iv', $ime_landing${"name":"Bombas de infusión","title":"Bomba de infusión hospitalaria | I-ME","description":"Bombas de infusión y de jeringa para UCI y hospitalización en Colombia. I-ME orienta el parque antes de cotizar.","intro":"Una bomba de infusión se elige por el servicio — UCI, hospitalización o pediatría —, la biblioteca de fármacos y quién la programa en el turno.","body":["Volumétricas vs jeringa no son intercambiables. I-ME ayuda a mezclar parque según UCI, pediatría y hospitalización general."],"faq":[{"q":"¿Cuántas bombas por cama UCI?","a":"Varía por protocolo. Partimos del mapa de terapias concurrentes del servicio, no de un ratio genérico de internet."}]}$ime_landing$::jsonb, $ime_landing${"name":"Infusion pumps","title":"Hospital infusion pumps | I-ME","description":"Infusion and syringe pumps for ICU and wards in Colombia. I-ME matches the fleet before a quote.","intro":"An infusion pump is chosen for the service — ICU, ward or pediatrics —, the drug library and who programs it each shift.","body":["Volumetric vs syringe pumps are not interchangeable. I-ME helps mix the fleet for ICU, pediatrics and general wards."],"faq":[{"q":"How many pumps per ICU bed?","a":"It varies by protocol. We start from concurrent therapies in the service — not a generic internet ratio."}]}$ime_landing$::jsonb),
  ('familia', 'anestesia', $ime_landing${"name":"Anestesia","title":"Máquinas de anestesia hospitalaria | I-ME","description":"Anestesia y ventilación de quirófano para hospitales en Colombia. Asesoría I-ME según carga quirúrgica.","intro":"Una máquina de anestesia se elige por quirófanos activos, tipo de cirugía y soporte de gases — no solo por pantalla.","body":["Cuando el proyecto incluye ventilación crítica aparte, separamos tipologías (quirófano vs UCI) para no subespecificar."],"faq":[{"q":"¿Anestesia con ventilador integrado?","a":"Es lo habitual en quirófano moderno. Validamos utilidades (O₂, aire, vacío) con ingeniería biomédica del sitio."}]}$ime_landing$::jsonb, $ime_landing${"name":"Anesthesia","title":"Hospital anesthesia machines | I-ME","description":"OR anesthesia and ventilation for hospitals in Colombia. I-ME advisory by surgical load.","intro":"An anesthesia machine follows active ORs, surgery mix and gas utilities — not only the display.","body":["When critical ventilation is separate, we split OR vs ICU typologies to avoid under-specifying."],"faq":[{"q":"Anesthesia with integrated ventilator?","a":"Common in modern ORs. We validate utilities (O₂, air, vacuum) with on-site biomed engineering."}]}$ime_landing$::jsonb),
  ('familia', 'ventiladores', $ime_landing${"name":"Ventiladores","title":"Ventiladores mecánicos hospitalarios | I-ME","description":"Ventilación mecánica para UCI adulto/pediátrica en Colombia. Orientación I-ME por tipología y soporte.","intro":"Ventilador UCI no es el mismo brief que quirófano o transporte. Definimos tipología con el servicio de cuidados intensivos.","body":["Adulto/pediátrico, modos y monitoreo asociados se cotizan tras aclarar población y protocolos — sin promesas clínicas inventadas."],"faq":[{"q":"¿Un ventilador sirve para adulto y pediátrico?","a":"Algunas referencias sí; otras no. Lo confirmamos por ficha técnica real del equipo cotizado."}]}$ime_landing$::jsonb, $ime_landing${"name":"Ventilators","title":"Hospital mechanical ventilators | I-ME","description":"Mechanical ventilation for adult/pediatric ICU in Colombia. I-ME guidance by typology and support.","intro":"ICU ventilators are not the same brief as OR or transport. We define typology with the critical-care service.","body":["Adult/pediatric scope, modes and related monitoring are quoted after clarifying population and protocols — no invented clinical claims."],"faq":[{"q":"Can one ventilator cover adult and pediatric?","a":"Some SKUs can; others cannot. We confirm from the real datasheet of the quoted unit."}]}$ime_landing$::jsonb),
  ('familia', 'terapia-de-infusion', $ime_landing${"name":"Bombas de infusión","title":"Bomba de infusión | página canónica en soluciones IV | I-ME","description":"Esta URL repite la familia de bombas de infusión. La página canónica es /es/familias/soluciones-iv/.","intro":"Las bombas de infusión están en la familia canónica. Esta página no se indexa.","body":["Revisamos estandarización de parque para reducir errores de programación y facilitar mantenimiento."],"faq":[{"q":"¿Puedo mezclar marcas de bombas?","a":"Sí, pero complica capacitación y repuestos. Preferimos un plan de estandarización por servicio."}]}$ime_landing$::jsonb, $ime_landing${"name":"Infusion pumps","title":"Infusion pumps | canonical family page | I-ME","description":"This URL repeats the infusion pump family. The canonical page is /en/families/soluciones-iv/.","intro":"Infusion pumps live on the canonical family page. This page is not indexed.","body":["We review fleet standardization to reduce programming errors and ease maintenance."],"faq":[{"q":"Can I mix pump brands?","a":"Yes, but training and spare parts get harder. We prefer a standardization plan by service."}]}$ime_landing$::jsonb)
